#define __IMPLEMENT_MODULE__CALL_INPUT_BACKPROPAGATION_KERNEL(index, costPartDerivWRTInput, costPartDerivWRTOutput, ConcreteModuleName, ValueType, InputKeyEnum, ParameterKeyEnum, OutputKeyEnum, InputTensorDimensionsPack, ParameterTensorDimensionsPack, OutputTensorDimensionsPack, TemplateParamTypesPack, TemplateParamNamesPack)                                \
