        getInputBackpropagationMemory()                                                                                                                                                                                                                                                                                                                                \
    );

/// Parameter

#define __IMPLEMENT_MODULE__IMPLEMENT_PARAM_BACKPROPAGATION_KERNEL(index, ConcreteModuleName, ValueType, InputKeyEnum, ParameterKeyEnum, OutputKeyEnum, InputTensorDimensionsPack, ParameterTensorDimensionsPack, OutputTensorDimensionsPack, TemplateParamTypesPack, TemplateParamNamesPack)                                                     \
    namespace                                                                                                                                                                                                                                                                                                                                     \
    {                                                                                                                                                                                                                                                                                                                                             \
        TEMPLATE_MACROS__TEMPLATE_PREFIX(TemplateParamTypesPack, TemplateParamNamesPack)                                                                                                                                                                                                                                                          \
